PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, platform_role TEXT NOT NULL DEFAULT 'user' CHECK(platform_role IN ('user','admin')), email_verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, user_agent TEXT, ip_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_sessions_token ON sessions(token_hash); CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
CREATE TABLE events (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, slug TEXT NOT NULL UNIQUE COLLATE NOCASE, title TEXT NOT NULL, event_type TEXT NOT NULL, lifecycle TEXT NOT NULL DEFAULT 'draft' CHECK(lifecycle IN ('draft','preview','published','active','live','completed','archived')), starts_at TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Africa/Lagos', location TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'guest_specific' CHECK(visibility IN ('public','private','guest_specific','password')), settings_json TEXT NOT NULL DEFAULT '{}', theme_json TEXT NOT NULL DEFAULT '{}', published_at TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_events_owner ON events(owner_id); CREATE INDEX idx_events_slug ON events(slug);
CREATE TABLE event_members (event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin','designer','guest_manager','checkin_staff','viewer')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(event_id,user_id));
CREATE TABLE occasions (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, title TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT, venue_name TEXT NOT NULL, address TEXT NOT NULL, latitude REAL, longitude REAL, audience TEXT NOT NULL DEFAULT 'all', is_private INTEGER NOT NULL DEFAULT 0 CHECK(is_private IN(0,1)), sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_occasions_event ON occasions(event_id,sort_order);
CREATE TABLE guest_groups (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'custom',UNIQUE(event_id,name));
CREATE TABLE households (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,seat_limit INTEGER NOT NULL DEFAULT 1 CHECK(seat_limit BETWEEN 1 AND 100));
CREATE TABLE guests (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,group_id TEXT REFERENCES guest_groups(id) ON DELETE SET NULL,household_id TEXT REFERENCES households(id) ON DELETE SET NULL,name TEXT NOT NULL,email TEXT,phone TEXT,access_token_hash TEXT UNIQUE,access_token_hint TEXT,language TEXT NOT NULL DEFAULT 'en',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','attending','declined','maybe')),party_size INTEGER NOT NULL DEFAULT 1 CHECK(party_size BETWEEN 1 AND 30),meal TEXT,dietary_notes TEXT,plus_one_name TEXT,table_name TEXT,checked_in_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_guests_event ON guests(event_id); CREATE INDEX idx_guests_status ON guests(event_id,status); CREATE INDEX idx_guests_token ON guests(access_token_hash);
CREATE TABLE guest_occasion_access (guest_id TEXT NOT NULL REFERENCES guests(id) ON DELETE CASCADE,occasion_id TEXT NOT NULL REFERENCES occasions(id) ON DELETE CASCADE,rsvp_status TEXT NOT NULL DEFAULT 'pending' CHECK(rsvp_status IN ('pending','attending','declined')),meal TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(guest_id,occasion_id));
CREATE TABLE rsvp_submissions (id TEXT PRIMARY KEY,guest_id TEXT NOT NULL REFERENCES guests(id) ON DELETE CASCADE,idempotency_key TEXT NOT NULL,payload_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(guest_id,idempotency_key));
CREATE TABLE experience_sections (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT,content_json TEXT NOT NULL DEFAULT '{}',access_rule TEXT NOT NULL DEFAULT 'all',sort_order INTEGER NOT NULL,is_visible INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_sections_event ON experience_sections(event_id,sort_order);
CREATE TABLE seating_tables (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,shape TEXT NOT NULL DEFAULT 'round',capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 100),x REAL NOT NULL DEFAULT 0,y REAL NOT NULL DEFAULT 0,UNIQUE(event_id,name));
CREATE TABLE budgets (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,category TEXT NOT NULL,budget_minor INTEGER NOT NULL DEFAULT 0 CHECK(budget_minor>=0),spent_minor INTEGER NOT NULL DEFAULT 0 CHECK(spent_minor>=0),currency TEXT NOT NULL DEFAULT 'NGN');
CREATE TABLE vendors (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,category TEXT NOT NULL,email TEXT,phone TEXT,contract_amount_minor INTEGER NOT NULL DEFAULT 0,payment_status TEXT NOT NULL DEFAULT 'due' CHECK(payment_status IN ('due','part_paid','paid')),notes TEXT);
CREATE TABLE announcements (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,created_by TEXT NOT NULL REFERENCES users(id),channel TEXT NOT NULL CHECK(channel IN ('email','sms','whatsapp')),audience TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','sent','failed')),sent_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE media (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,guest_id TEXT REFERENCES guests(id) ON DELETE SET NULL,object_key TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,caption TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE analytics_events (id TEXT PRIMARY KEY,event_id TEXT REFERENCES events(id) ON DELETE CASCADE,guest_id TEXT REFERENCES guests(id) ON DELETE SET NULL,type TEXT NOT NULL,session_hash TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_analytics_event ON analytics_events(event_id,type,occurred_at);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY,event_id TEXT REFERENCES events(id) ON DELETE SET NULL,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',request_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_audit_event ON audit_logs(event_id,created_at);
